            lbl.ForeColor = System.Drawing.Color.FromArgb(15, 23, 42);
            lbl.Location = new System.Drawing.Point(10, y + 14);
            lbl.Name = "lbl" + text.Replace(" ", "").Replace("(", "").Replace(")", "");
            lbl.Text = text;
